import { CallOutlined, EmailOutlined } from '@mui/icons-material';
import { Link } from 'react-router-dom';
import { 
  AppBar,
  Container,
  Box,
  Typography,
  IconButton,
  Stack
} from '@mui/material';

import DarkThemeIcon2ResearcherONE from '../svgs/Dark Theme/(DarkTheme)Icon2ResearcherONE.svg';


function Footer() {
  return (
    
    <AppBar 
      
      position="static" 
      sx={{ 
        backgroundColor: '#172F5D',
        top: 'auto',
        mt: '-50px',
        bottom: 0,
        zIndex: (theme) => theme.zIndex.drawer + 1,
        height: 125,

      }}
    >
      <Container maxWidth="xl" 
      sx={{ 
        display: 'flex',
        
        justifyContent: 'space-between',
        alignItems: 'center',
        position: 'relative',
        height: '100%'
      }}>
        {/* Left Side - Contact Info */}
        <Stack direction="column" spacing={1}>
          <Box display="flex" alignItems="center">
            <CallOutlined fontSize="medium" sx={{ mr: 1 }} />
            <Typography fontSize={'12px'} fontFamily={'Raleway, sans-serif'} >1 (800) 123 - 4567</Typography>
          </Box>
          <Box display="flex" alignItems="center">
            <EmailOutlined fontSize="medium" sx={{ mr: 1 }} />
            <Typography fontSize={'12px'} fontFamily={'Raleway, sans-serif'}>placeholderEmail@uky.edu</Typography>
          </Box>
        </Stack>

        {/* Centered Logo & Copyright */}
        <Box sx={{
          position: 'absolute',
          left: '50%',
          top: '50%',
          transform: 'translate(-50%, -50%)',
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center'
        }}>
          <IconButton
            component={Link}
            to="/"
            sx={{ 
              p: 0, 
              width: 125,  // Slightly reduced for better proportion
              height: 125,
              '&:hover': { backgroundColor: 'transparent' }
            }}
          >
            <img 
              src={DarkThemeIcon2ResearcherONE} 
              alt="Footer ResearcherONE Logo" 
              style={{ height: '100%', width: 'auto' }}
            />
          </IconButton>
          <Typography fontFamily={'Raleway, sans-serif'} fontSize={'8px'} sx={{ mt: '-20px'}}>
            © {new Date().getFullYear()} ResearcherONE
          </Typography>
        </Box>
      </Container>
    </AppBar>
  );
}

export default Footer;