import imagePlaceholder from '../assets/background.jpeg';
import { Box, Typography } from '@mui/material';
import colors from '../assets/Colors';

const Home = () =>  {
  return (
    <>
      <Box
        sx={{
          position: 'relative',
          width: '100%',
          height: '80vh',
          overflow: 'hidden',
        }}
      >
        <Box
          component="img"
          src={imagePlaceholder}
          alt="image placeholder for now"
          sx={{
            width: '100%',
            height: '100%',
            objectFit: 'cover',
            opacity: 0.6, 
          }}
        />
        <Box
          sx={{
            position: 'absolute',
            top: 0,
            left: 0,
            height: '100%',
            width: '100%',
            display: 'flex',
            flexDirection: 'column',
            justifyContent: 'center',
            alignItems: 'center',
            textAlign: 'center',
            color: colors.darkBlue,
            px: 2,
          }}
        >
          <Typography
            variant="h3"
            sx={{fontFamily: 'Raleway, sans-serif',fontWeight: 'bold',mb: 2,
            }}
          >
            What is ResearcherONE?
          </Typography>
          <Typography
            variant="h6"
            sx={{
              fontFamily: 'Raleway, sans-serif',
              maxWidth: '900px',
            }}
          >
            ResearcherONE is an onboarding and project management tool that provides an all-in-ONE platform to improve researcher knowledge, efficiency, and integration within a large university enterprise.
          </Typography>
        </Box>
      </Box>

      {/* if spacing needed*/}
      {/* <Box sx={{ height: '40px' }} /> */}
    </>
  );
}

export default Home;
