import { Link } from 'react-router-dom';
import IconResearcherONE from '../svgs/IconResearcherONE.svg';
import { 
  AppBar,
  Toolbar,
  Container,
  Box,
  Button,
  IconButton
} from '@mui/material';

import HeaderButton from './HeaderButton';
import colors from '../assets/Colors'
import { AccountCircleOutlined } from '@mui/icons-material';

function Header({isLoggedIn}) {
  return (
    <AppBar sx={{ backgroundColor: colors.headerBkgd, position: 'sticky', zIndex: (theme) => theme.zIndex.drawer + 1 }}>
      <Container maxWidth="xl">
        <Toolbar disableGutters>
        <IconButton
          component={Link}
          to="/"
          sx={{ mr: 2, p: 0, width: 80, height: 80,
            '&:hover': {
              backgroundColor: 'transparent'
            }}}>
          <img 
            src={IconResearcherONE} 
            alt="ResearcherONE Logo" 
            style={{ height: '100%', width: 'auto', padding: 8 }}/>
        </IconButton>
        <Box sx={{ display: 'flex', flexGrow: 1, justifyContent: 'center', gap: 10 }}>
        {/* could remove since icon leads you back but that's personal choice 
            leaving it for now because there would be no other buttons if user is not logged in */}
        <HeaderButton
          webPath='/'
          name='Home'
          ></HeaderButton>
          {isLoggedIn && (
            <> 
            <HeaderButton
            webPath='/dashboard'
            name='Dashboard'
            >
            </HeaderButton>
            <HeaderButton
             webPath='/postAward'
             name='Post Award'
            ></HeaderButton>
            </>
          )}
        </Box>
        <Button 
          component={Link}
          to="/login" 
          sx={{ backgroundColor: '#2A5C6D', color:'#FFFFFF', borderRadius: '50px', fontSize:'10px', fontWeight: 'bold'}}>
            <AccountCircleOutlined fontSize='small' sx={{ pr: '3px'}}/>
            Sign In
        </Button>
        </Toolbar>
      </Container>
    </AppBar>
  );
}

export default Header;