// component for Links on Module pages -- didn't realize there was a 
// Link component from mui so can remove if desired 

// <ModuleLink
//     link= outside webpage want to go to
//     text= text to link the link to >

import { Box,Button } from "@mui/material";
import colors from "../assets/Colors";

const ModuleLink = ({link,text}) =>{
return (<Box sx={{paddingLeft:4.5}}>
                    <Button   
                    size="small"
                    disableRipple
                    component="a"
                    href={link}
                    target="_blank" 
                    rel="noopener noreferrer" //security measure for external sites from this one 
                    variant="text"
                    sx={{
                        backgroundColor:'transparent',
                        display: "inline-flex", // Prevents full width while keeping button behavior
                        alignSelf: "flex-start", // Align with content
                        color: colors.highlightOrange,
                        fontSize: '.8rem',
                        textTransform: 'none',
                        fontFamily: 'Raleway, sans-serif',
                        minWidth: "auto", // Prevents unnecessary width
                        justifyContent: "start", // Ensures text aligns properly
                        }}>{text}
                </Button>
                </Box>
);
                };
export default ModuleLink