import ModuleStep from "../../components/ModuleStep";
import ModuleTitle from "../../components/ModuleTitle";
import ModuleLink from "../../components/ModuleLink";
import {Stack, Typography, Box } from '@mui/material';
import ModuleQuestion from "../../components/ModuleQuestion";
import colors from "../../assets/Colors";

const ModuleThree = () => {
    return (

        <Stack direction='column' >
            <ModuleTitle
                number='3'
                title='Welcome to Step 3:'
                content='Create Source Documents/Case Report Forms'>
            </ModuleTitle>
            <ModuleStep
                title='3.1 Create Source Documents'
                content='In research, a source document or Case Report Form (CRF) is a standardized document used in research studies 
                or clinical trials to collect specific, protocol-defined data from each participant, ensuring consistent and 
                accurate data collection for analysis and reporting. They are designed to capture the data needed to answer the 
                research question or objectives of the research study. They are crucial for maintaining the quality and integrity
                 of clinical data, ensuring that the data collected is organized, understandable, reproducible, reliable, updated, 
                 and verified for accuracy. '>
            <Typography sx={{paddingX: 5, fontFamily:'Raleway, sans-serif', fontSize:'.8rem'}}>  These forms can either be paper based or electronic. Tools for electronic based forms commonly used in research
            settings are Redcap and Qualtrics. If you want to use Redcap, we can help you set that up in a later step. 
            <br></br>
            Please use the following report to help you with your forms. 
            </Typography>
             <Box paddingX={5}>
              
              <a
                href="\Basics of Case Report Form Designing in Clinical Research.pdf"
                target="_blank"
                rel="noopener noreferrer"
                style={{ color: colors.highlightOrange, textDecoration: 'underline', fontSize:'.8rem',fontFamily:'Raleway, sans-serif' }}
              >
                 Basics of Case Report Form Designing in Clinical Research
                </a>
            </Box>
            </ModuleStep>

            <ModuleStep
                title='3.2 Attach to your IRB Application'
                content="Once you have completed the needed forms, please attach to your IRB application.">
            </ModuleStep>

       </Stack>

      );
    };
    
export default ModuleThree;