import ModuleStep from "../../components/ModuleStep";
import ModuleTitle from "../../components/ModuleTitle";
import ModuleLink from "../../components/ModuleLink";
import {Stack, Typography } from '@mui/material';
import ModuleQuestion from "../../components/ModuleQuestion";

const ModuleFive = () => {
    return (

        <Stack direction='column' >
            <ModuleTitle
                number='5'
                title='Welcome to Step 5:'
                content='Database Setup'>
            </ModuleTitle>
            <ModuleStep
                title='5.1 Develop a Data Management and Sharing Plan'
                content='In research, effective data storage involves choosing appropriate storage solutions, 
                implementing secure practices, and establishing backup routines to ensure data integrity, accessibility, 
                and compliance with relevant regulations and ethical guidelines. Align your research data with public, private, 
                or regulated classification to choose the right option and utilize university or large institutional storage solutions 
                to be sure you follow their policies for compliance.'>
                    <br></br>
                <Typography sx={{paddingX: 5, fontFamily:'Raleway, sans-serif', fontSize:'.8rem'}}> Common sources of data include local storage (excel files), 
                web based storage (Redcap), or cloud storage (Microsoft Teams and OneDrive). Develop a data management and sharing plan 
                that outlines where and how you will store your data, who will be able to access it, and how long you will keep it 
                which should comply with your University or institutional policy. Be sure to comply with relevant data protection regulations
                 such as HIPAA, FERPA, or GDPR.</Typography>
                <ModuleLink
                link='https://sharing.nih.gov/data-management-and-sharing-policy/planning-and-budgeting-for-data-management-and-sharing/writing-a-data-management-and-sharing-plan#after'
                text='NIH’s Policy on Data Management and Sharing Plans [Includes Sample Plans]'>

                </ModuleLink>
            </ModuleStep>

            <ModuleStep
                title='5.2 Generate a Data Management and Sharing Plan'
                content="Start a Data Management and Sharing Plan with our AI-powered software.">
             <ModuleQuestion
             question='Need help with a data management and sharing plan?'
             yesResponse={<Typography sx={{fontFamily:'Raleway, sans-serif', fontSize:'.8rem'}}>No problem, let us get you started with a plan you can adjust to your research strategy.</Typography>}
            /*
            Create a [Generate Data Management Plan] Button that would trigger written code or API call to 
            AI platform to generate word document based on University/NIH templates stored in a folder. 
            */
             noResponse={<Typography sx={{fontFamily:'Raleway, sans-serif', fontSize:'.8rem'}}>No problem, let's move on.</Typography>}>
            </ModuleQuestion>
            </ModuleStep>

            <ModuleStep
                title='5.3 (Optional) Redcap Data Storage'>
             <ModuleQuestion
             question='Will you be using Redcap for your data storage?'
             yesResponse={<Typography sx={{fontFamily:'Raleway, sans-serif', fontSize:'.8rem'}}>Great, we can help with that. Here is a data dictionary template to get you started. 
                Please upload this template into Redcap using the data dictionary option. Advance knowledge of Redcap is recommended.</Typography>}
            /*
            Create a [Download template data dictionary for Redcap] button/link
            Need to supply Redcap data dictionary excel file.
            */

             noResponse={<Typography sx={{fontFamily:'Raleway, sans-serif', fontSize:'.8rem'}}>No problem, let's move on.</Typography>}>
            </ModuleQuestion>
            </ModuleStep>

       </Stack>

      );
    };
    
export default ModuleFive;