import ModuleStep from "../../components/ModuleStep";
import ModuleTitle from "../../components/ModuleTitle";
import ModuleLink from "../../components/ModuleLink";
import {Stack,Box, Typography } from '@mui/material';
import ModuleQuestion from "../../components/ModuleQuestion";

const ModuleTwo = () => {
    return (

        <Stack direction='column' >
            <ModuleTitle
                number='2'
                title='Welcome to Module 2:'
                content='Create Consent Documents'>
            </ModuleTitle>
            
            <ModuleStep
                title='2.1 Create Consent Documents'
                content='In research, an informed consent form is a documenthat outlines the
                details of a study, ensuring participants understand the risks and benefits before
                voluntarily agreeing to participate, protecting their autonomy and rights. The primary purpose
                of an informed consent form is to ensure that potential research participants are fully informed
                about the study before making a decision to participate. Obtaining informed consent is a fundamental
                ethical and legal requirement in research involving human participants. It ensures that participants
                are not coerced or manipulated into participating.'
                >
                <Typography sx={{paddingX: 5, fontFamily:'Raleway, sans-serif', fontSize:'.8rem'}}>There are two types of consents typically utilized in human research:
                    <br></br>
                1. Cover Letters- typically used with survey research 
                <br></br>
                2. Full Informed Consent with or without HIPAA language.</Typography>
                {/* Lets help you generate one using your University template. Which format would you like to generate? 
                [Clickable boxes for Cover Letter, Informed Consent, Informed Consent with HIPAA]*/}
            </ModuleStep>

            <ModuleStep
                title='2.2 Review Document'
                content='Please review the document for individualized information you may need to add 
                or revise based on the specifics of your current study.'>
                <ModuleQuestion
                question='Are you recruiting individuals less than 18 years of age?'
                yesResponse={
                <>
                <Box paddingX={4}>
                <Typography sx={{fontFamily:'Raleway, sans-serif', fontSize:'.8rem'}}>Ok, great, you will need an assent form as well. Let’s generate one for you using your University template.</Typography>
                </Box>
                </>
                }
                noResponse={
                <>
                <Box paddingX={4}>
                <Typography sx={{fontFamily:'Raleway, sans-serif', fontSize:'.8rem'}}>No problem, you’re all set for now. Attach your consent form to your IRB application.</Typography>
                </Box>
                </>
                }
                >
                </ModuleQuestion> 
            </ModuleStep>

       </Stack>

      );
    };
    
export default ModuleTwo;