import ModuleStep from "../../components/ModuleStep";
import ModuleTitle from "../../components/ModuleTitle";
import ModuleLink from "../../components/ModuleLink";
import {Stack, Typography } from '@mui/material';
import ModuleQuestion from "../../components/ModuleQuestion";

const ModuleFour = () => {
    return (

        <Stack direction='column' >
            <ModuleTitle
                number='4'
                title='Welcome to Step 4:'
                content='Create Marketing Materials'>
            </ModuleTitle>
            <ModuleStep
                title='4.1 Generate Marketing Materials'
                content='In research, marketing materials, like brochures, flyers, and social media posts, 
                are used to promote a study, attract participants, or disseminate findings, helping researchers 
                reach their target audience and achieve their research goals. Types of materials may include 
                brochures, flyers, website or digital content such as infographics, and social media posts. 
                Be sure to let the IRB know about each specific method you’d like to use for marketing your study.'>
                <ModuleQuestion
                question='Would you like to develop marketing for your study?'
                /*
                Alternative yesResponse=Which type of marketing would you like help with? [Flyer, Brochure, Infographic]
                */
                yesResponse={<ModuleQuestion
                question='Do you have a specific image in mind you’d like to use?'
                yesResponse={<Typography sx={{fontFamily:'Raleway, sans-serif', fontSize:'.8rem'}}>Ok great, please describe the type of image you would like to use in your marketing:</Typography>}
                /*
                [open field box for text to prompt AI model to generate image]  
                Continue to prompt until you are happy with the generated image. Copy and paste into your flyer.
                */
                noResponse={<Typography sx={{fontFamily:'Raleway, sans-serif', fontSize:'.8rem'}}>No problem, let’s move on to the next step.</Typography>}>

                </ModuleQuestion>}
                noResponse={<Typography sx={{fontFamily:'Raleway, sans-serif', fontSize:'.8rem'}}>No problem, let’s move on to the next step.</Typography>}>
                </ModuleQuestion>
            </ModuleStep>

            <ModuleStep
                title='4.2 Get University Approval for Marketing'
                content='Once your marketing is generated, you will need to send your finished product to your 
                University Public Relations (PR) department for approval. They can help with University logos and required language 
                for your advertisement.'>
                    <ModuleLink
                    link='https://www.research.uky.edu/office-research-integrity/irb-application-instructions-advertisements'
                    text='Find more information here'>
                    </ModuleLink>
            </ModuleStep>
       </Stack>
      );
    }; 
export default ModuleFour;