import { 
  Box,
  Button,
  Divider,
  Stack
} from '@mui/material';

import { Link } from 'react-router-dom';
import { ArrowForwardIos } from '@mui/icons-material';
import { useState } from 'react';

function StepSideBar () {
  const [isStep1Expanded, setIsStep1Expanded] = useState(false);

  const toggleStep1 = () => {
    setIsStep1Expanded(!isStep1Expanded);
  };

  return (
    <Box 
      sx={{
        position: 'sticky',
        left: 0,
        top: 0, 
        bottom: 0,
        width: '25vh',
        height: '100vh',
        bgcolor: '#D4E3E4',
        zIndex: (theme) => theme.zIndex.drawer - 1,
      }}
    >
      <Stack spacing='5px' sx={{ paddingTop: '10px', display: 'flex', alignItems: 'center' }}>
        <Box sx={{ display: 'flex', alignItems: 'center' }}>  
            <Button 
              component={Link}
              to='/postAward/moduleOne'
              sx={{ 
                color: '#172F5D', 
                fontWeight: 'semibold',
                p: 0,         
                minWidth: 0      
              }}
            >
              Step 1
            </Button>
            <ArrowForwardIos 
              fontSize='small' 
              sx={{ 
                pl: '8px',
                transform: isStep1Expanded ? 'rotate(90deg)' : 'rotate(0deg)',
                transition: 'transform 0.2s ease-in-out',
                cursor: 'pointer',
                m: 0,
                position: 'relative',
              }} 
              onClick={toggleStep1}
            />
          </Box>
          <Divider sx={{ width: '25vh' }}/>
        
        {/* Conditionally render sub-items */}
        {isStep1Expanded && (
          <Box sx={{ textAlign: 'left', width: '100%' }}>
            <Box sx={{
              fontSize: '12px', 
              color: '#172F5D', 
              fontWeight: 'light',
              m: '2px',
              pl: '16px' // Add padding to indent sub-items
            }}>
              1.1 Get Started with IRB
            </Box>
            <Divider sx={{ width: '25vh' }}/>
            <Box sx={{
              fontSize: '12px', 
              color: '#172F5D', 
              fontWeight: 'light',
              m: '4px',
              pl: '16px' // Add padding to indent sub-items
            }}>
              1.2 Background Information
            </Box>
            <Divider sx={{ width: '25vh' }}/>
            <Box sx={{
              fontSize: '12px', 
              color: '#172F5D', 
              fontWeight: 'light',
              m: '4px',
              pl: '16px' // Add padding to indent sub-items
            }}>
              1.3 Required Trainings for Approval
            </Box>
            <Divider sx={{ width: '25vh' }}/>
          </Box>
        )}
        
        

        <Box>
          <Button component={Link}
          to='/postAward/moduleTwo' sx={{ color: '#172F5D', fontWeight: 'semiBold'}}>
            Step 2
            <ArrowForwardIos fontSize='small' sx={{ pl: '8px'}} />
          </Button>
        </Box>
        <Divider sx={{ width: '25vh' }}/>

        <Box>
          <Button component={Link}
              to='/postAward/moduleThree' sx={{ color: '#172F5D', fontWeight: 'semiBold'}}>
            Step 3
            <ArrowForwardIos fontSize='small' sx={{ pl: '8px'}} />
          </Button>
        </Box>
        <Divider sx={{ width: '25vh' }}/>

        <Box>
          <Button component={Link}
              to='/postAward/moduleFour' sx={{ color: '#172F5D', fontWeight: 'semiBold'}}>
            Step 4
            <ArrowForwardIos fontSize='small' sx={{ pl: '8px'}} />
          </Button>
        </Box>
        <Divider sx={{ width: '25vh' }}/>

        <Box>
          <Button component={Link}
              to='/postAward/moduleFive' sx={{ color: '#172F5D', fontWeight: 'semiBold'}}>
            Step 5
            <ArrowForwardIos fontSize='small' sx={{ pl: '8px'}} />
          </Button>
        </Box>
        <Divider sx={{ width: '25vh' }}/>

        <Box>
          <Button component={Link}
              to='/postAward/moduleSix'
              sx={{ color: '#172F5D', fontWeight: 'semiBold'}}>
            Step 6
            <ArrowForwardIos fontSize='small' sx={{ pl: '8px'}} />
          </Button>
        </Box>
        <Divider sx={{ width: '25vh' }}/>

        <Box>
          <Button 
          component={Link}
          to='/postAward/moduleSeven' sx={{ color: '#172F5D', fontWeight: 'semiBold'}}>
            Step 7
            <ArrowForwardIos fontSize='small' sx={{ pl: '8px'}} />
          </Button>
        </Box>
        <Divider sx={{ width: '25vh' }}/>

      </Stack>
    </Box>
  );
}

export default StepSideBar;