import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import { CssBaseline, ThemeProvider, createTheme } from '@mui/material';
import { Box, Container } from '@mui/material'

import Header from './components/Header';
import Footer from './components/Footer';

import { useState } from 'react';
import Home from './pages/Home';
import Dashboard from './pages/Dashboard';
import PostAward from './pages/PostAward';
import NewProject from './pages/NewProject';
import Login from './pages/Login';
import ModuleOne from './pages/ModulePages/ModuleOne'
import ModuleLayout from './pages/ModulePages/ModuleLayout';
import ModuleTwo from './pages/ModulePages/ModuleTwo';
import ModuleThree from './pages/ModulePages/ModuleThree';
import ModuleFour from './pages/ModulePages/ModuleFour';
import ModuleFive from './pages/ModulePages/ModuleFive';
import ModuleSix from './pages/ModulePages/ModuleSix';
import ModuleSeven from './pages/ModulePages/ModuleSeven';

const theme = createTheme();

function App() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);

  const handleLogin = () => setIsLoggedIn(true);
  
  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />
      <Router>
        <Box display ='flex' flexDirection='column' minHeight ='100vh'>
        <Header isLoggedIn= {isLoggedIn} />
        
        <Box component='main' flexGrow='1' paddingBottom={5}>
            <Routes>
              <Route path="/" element={<Home />} />
              <Route path="/dashboard" element={<Dashboard />} />
                <Route path="/postAward" element={<ModuleLayout />}>
  <Route index element={<PostAward />} /> {/* This renders at /postAward */}
  <Route path="moduleOne" element={<ModuleOne />} />
  <Route path="moduleTwo" element={<ModuleTwo />} />
  <Route path="moduleThree" element={<ModuleThree />} />
  <Route path="moduleFour" element={<ModuleFour />} />
  <Route path="moduleFive" element={<ModuleFive />} />
  <Route path="moduleSix" element={<ModuleSix />} />
  <Route path="moduleSeven" element={<ModuleSeven />} />
</Route>
              <Route path="/newProject" element={<NewProject />} />
              <Route path='/login' element={<Login onLogin={handleLogin} />} />
            </Routes>
         
        </Box>
         {/* <Box sx={{ height: '10'}}></Box> */}
        <Footer />
        </Box>
      </Router>
    </ThemeProvider>
  );
}

export default App;