import PostAwardStep from '../components/PostAwardStep';
import StartButton from '../components/StartButton';
import colors from '../assets/Colors';
import { 
    Box,
    Paper,
    Stack,
    Typography,
  } from '@mui/material';

function PostAward() {
    return ( 
      <div style={{ display: 'flex' }}> 
        <Box component="main" sx={{ flexGrow: 1 }}> {/* ← Main content area */}
            
            <Box 
            sx={{
            position: 'absolute', // or 'absolute' depending on your layout
            top: '64px', // adjust this to match your header height
            left: 0,
            right: 0,
            height: '22vh', 
            bgcolor: '#172F5D', 
            zIndex: (theme) => theme.zIndex.drawer - 2,
            display: 'flex',
            justifyContent: 'center'
            }}
        >
            <Stack direction={'column'} sx={{ display: 'flex', alignItems: 'center' }}>
                <Typography fontFamily={'Raleway, sans-serif'} fontSize={'28px'} fontWeight={'bold'} sx={{ color: '#B2D9DC', mt: '45px', ml: '175px'}}>
                    Welcome to the Post Award Page
                </Typography>
                <Typography fontFamily={'Raleway, sans-serif'} fontSize={'16px'} fontWeight={'medium'} sx={{ color: '#FFFFFF', mt: '10px', ml: '175px'}}>
                    Congratulations on receiving funding for your research! Here, you will find step-by-step instructions
                    that will help guide you through the Post-Grant Process. Check off each step as you complete them to 
                    track your progress.
                </Typography>
            </Stack>
        </Box>

            <Stack direction={'column'} sx={{ display: 'flex', alignItems: 'left', mt: '125px', ml: '100px' }}>
                
                <Stack direction={'row'} spacing={'100px'}
                    pt={'40px'}
                    pb={'10px'} 
                >
                    <Paper elevation='3' sx={{ width: '35vh', height: '30vh', bgcolor: colors.color1Blue, color: colors.white, 
                        pt: '10px',
                        pl: '15px',
                        pr: '15px'
                        }}>
                        <Typography fontFamily={'Raleway, sans-serif'} fontSize={'18px'} fontWeight={'bold'}>Step 1:</Typography>
                        <Typography fontFamily={'Raleway, sans-serif'} fontSize={'15px'} fontWeight={'medium'} sx={{ mt: '13px',mb:'25px'}}>
                            IRB Review
                        </Typography>
                        <StartButton
                            path='/postAward/moduleOne'
                        ></StartButton>

                    </Paper>

                    <PostAwardStep
                        stepNumber='2'
                        stepName = 'Create consent document(s) using EIRB templates'
                        webPath = '/postAward/moduleTwo'
                    ></PostAwardStep>
                     <PostAwardStep
                        stepNumber='3'
                        stepName = 'Create source documents and case report forms'
                        webPath = '/postAward/moduleThree'
                    ></PostAwardStep>
                </Stack>

                <Stack direction={'row'} spacing={'100px'}
                    pt={'40px'}
                    pb={'10px'} 
                >
                     <PostAwardStep
                        stepNumber='4'
                        stepName = 'Create marketing materials (Requires Approval)'
                        webPath = '/postAward/moduleFour'
                    ></PostAwardStep>
                    
                       <Paper elevation='3' sx={{ width: '35vh', height: '30vh', bgcolor: colors.color1Blue, color: colors.white, 
                        pt: '10px',
                        pl: '15px',
                        pr: '15px'
                        }}>
                        <Typography fontFamily={'Raleway, sans-serif'} fontSize={'18px'} fontWeight={'bold'}>Step 5:</Typography>
                        <Typography fontFamily={'Raleway, sans-serif'} fontSize={'15px'} fontWeight={'medium'} sx={{ mt: '13px',mb:'25px'}}>
                        Create database
                        </Typography>
                        <StartButton
                            path='/postAward/moduleFive'
                        ></StartButton>

                    </Paper>
                     <PostAwardStep
                        stepNumber='6'
                        stepName = 'Create regulatory electronic notebook'
                        webPath = '/postAward/moduleSix'
                    ></PostAwardStep>
                     
                </Stack>
                <Stack direction={'row'} spacing={'100px'}
                    pt={'40px'}
                    pb={'10px'} 
                    sx={{justifyContent:'left'
                    }}
                >
                    <PostAwardStep
                        stepNumber='7'
                        stepName = 'Getting started with IRB and EIRB login'
                        webPath = '/postAward/moduleSeven'
                    ></PostAwardStep>
                </Stack>
            </Stack> 
        </Box>
      </div>
    );
  }
  
  export default PostAward;
  


