// component for the blue question boxes with yes no buttons 
//    answer is state of card and changes based on which button is pressed,
//    which is passed by the ModuleYesNo component
//      answer == null -> shows initial question and the Yes and No buttons
//      answer == 'yes' -> show intended response if user presses yes
//      answer == 'no' -> show intended response if user presses yes

// <ModuleQuestion
// question= question to ask 
// yesResponse={<>
//    <Box
//    sx={{paddingX:4.5}}> - for formatting 
//    components desired for response, <Typography> - most likely
// </>}

// noResponse={<>
//     <Box
//    sx={{paddingX:4.5}}> - for formatting 
//   components desired for response, <Typography> - most likely
//  </>
// }>
//    </ModuleQuestion> 


import colors from '../assets/Colors'
import { useState } from 'react';
import { Container, Paper, Typography, Stack, IconButton, Box} from '@mui/material';
import ModuleYesNo from './ModuleYesNo';
import ArrowBack from '@mui/icons-material/ArrowBack';
import '../assets/font.css'

const ModuleQuestion = ({ question, yesResponse, noResponse }) => {
  const[answer,setAnswer] =useState(null);

  const handleAnswer =(response)=>{setAnswer(response)}
  return (
    <Container 
     sx={{ 
      display: "flex", 
      justifyContent: "center",       
      width: "100%" }}>
        <Paper    
          elevation={3} 
          square = {false}
          sx={{ 
            backgroundColor:colors.color1Blue,
            color:colors.white,
            textAlign: 'center',
            width: "100%",
            height: "auto",
            position:'relative'
          }}
        >
        {answer !== null && (
          <Box paddingBottom={1.5}>
           <IconButton         
           onClick={() => setAnswer(null)}
           disableRipple
           size='small'
           sx={{
            position:'absolute',
            top:3,
            left:3,
            color: colors.highlightOrange
           }}
           >
             <ArrowBack fontSize='inherit'></ArrowBack>
           </IconButton>
           </Box>
        )}
        <Stack direction='column' paddingY={2}>
            {/* if button has not been clicked show question  */}
          
            {answer === null && (
            <>

              <Typography 
                paddingBottom={1} 
                sx={{ fontFamily: 'Raleway, sans-serif', fontSize: '.8rem' }}
              >
              {question}
              </Typography>
              <ModuleYesNo onAnswer={handleAnswer} />
            </>
          )}
          {answer === 'yes' && (
            
           
            yesResponse
            
            
          )}
          {answer === 'no' && (
           
            noResponse
            
          )}
        </Stack>
        </Paper>
    </Container>
  );
};
  
  export default ModuleQuestion;