import ModuleStep from "../../components/ModuleStep";
import ModuleTitle from "../../components/ModuleTitle";
import ModuleLink from "../../components/ModuleLink";
import {Stack, Typography } from '@mui/material';
import ModuleQuestion from "../../components/ModuleQuestion";

const ModuleSix = () => {
    return (

        <Stack direction='column' >
            <ModuleTitle
                number='6'
                title='Welcome to Step 6:'
                content='Electronic Regulatory Notebook Setup'>
            </ModuleTitle>
            <ModuleStep
                title='6.1 Create Electronic Regulatory Notebook Template'
                content='In research, a regulatory notebook, also known as a regulatory binder or study file, 
                is a collection of documents that demonstrates compliance and regulatory requirements, often reviewed during 
                audits and inspections. These files can also be organized collections of electronic information and can include 
                things like articles, books, and multimedia, that are searchable and often retrievable in full-text format, 
                aiding researchers in finding study information quickly and efficiently.  Typically, these documents should, at a minimum, 
                include: '>
                <Typography sx={{paddingX: 7, fontFamily:'Raleway, sans-serif', fontSize:'.8rem'}}>
                                   1. Grant related documents and protocol 
                <br></br>
                2. IRB documents and correspondence (informed consent-signed and unsigned, IRB protocol, investigator brochure) 
                <br></br>
                3. Training and qualification documents (license, CVs, training certificates, financial disclosures) 
                <br></br>
                4. Sponsor documentation and communication 
                <br></br>
                5. Agreements folder (confidentiality agreement, data sharing, material transfer agreements etc) 
                <br></br>
                6. Logs related to adverse events, irb updates, withdrawals, screening and enrollment etc) 
                <br></br>
                7. Laboratory protocols and manual of operations (certifications) 
                <br></br>
                8. Data and Safety Monitoring 
                <br></br>
                <br></br>
    </Typography>
                <Typography sx={{paddingX: 5, fontFamily:'Raleway, sans-serif', fontSize:'.8rem'}}>
                    
                Whether you want to store on localized servers or within cloud environments such as Microsoft TEAMS/Google Drive, 
                ResearcherONE can help.</Typography>
                <ModuleLink
                link='https://www.research.uky.edu/office-research-integrity/getting-started'
                /* Change link to Download Electronic Regulatory Notebook zip folder */
                text='Download our template for localized folder storage here.
                Included in these folders are standard logs commonly used. Revise and reorganize to taste.'>
                </ModuleLink>
            </ModuleStep>

       </Stack>

      );
    };
    
export default ModuleSix;