// component for the grey boxes on the each step x page 
//describes what needs to be done within a step (look at step x page to see)
/* <ModuleStep
      title='x.y Title of step'
      content='text of main body of '>
     **can include other components within ModuleStep**
      <ModuleLink>, <ModuleQuestion>, ect
    </ModuleStep> */

// could alter content to not be constrained to 
// just Typography component because some steps needs more 
// text after content which results in adding more 
//  Typography components which defeats the purpose
//      content- want all typography components with 
//        this consistent style  
//          sx={{paddingX: 5, fontFamily:'Raleway, sans-serif', fontSize:'.8rem'}}
//      include other components ? but could just stick with children 

import colors from '../assets/Colors'
import { Container, Paper, Typography, Stack, Checkbox } from '@mui/material';

const ModuleStep = ({  title, content, children }) => {
  return (
    <Container 
     sx={{ 
      display: "flex",
      paddingTop: 5, 
      justifyContent: "center", 
      width: "100%" }}>
      <Paper    
        elevation={3} 
        square={false}
        sx={{ 
          backgroundColor:colors.mainGrey,
          width: "90%",
          height: "auto",
        }}
      >
        <Stack 
        direction='column' 
        paddingBottom={3}
        spacing={.5} 
        justifyContent='center' 
        marginLeft={2} > {/*alter margin */}
          <Stack  
          direction='row' 
          sx={{
            width:'100%', 
            justifyContent:"space-between", 
            alignItems:'center'}} >
              <Typography  paddingTop={1}sx={{fontWeight:'bold',fontFamily:'Raleway, sans-serif',fontSize:'1rem', color:colors.darkBlue}}>{title}</Typography>
              <Checkbox default size='small' 
                sx={{
                  color:colors.highlightOrange,  
                  '&.Mui-checked': {color: colors.highlightOrange}}}>
              </Checkbox>
          </Stack>
          <Typography  sx={{paddingX: 5, fontFamily:'Raleway, sans-serif', fontSize:'.8rem'}}>{content}</Typography>
          {children}
        </Stack>
      </Paper>
    </Container>
  );
};
  
export default ModuleStep;