// component for blue box on step x page that welcomes 
// user to a step 
/* <ModuleTitle
      number='X'
      title='Welcome to Step X:'
      content='name of particular step '>
  </ModuleTitle> */


import colors from '../assets/Colors'
import '../assets/font.css'
import { Container, Paper, Typography, Stack } from '@mui/material';

const ModuleTitle = ({ number, title, content }) => {
    return (
      <Container 
       sx={{ 
        display: "flex", 
        justifyContent: "center", 
        width: "100%" }}>
        <Paper    
          elevation={3} 
          square
          sx={{ 
            backgroundColor:'rgba(127, 191, 196,.6)',
            color:colors.darkBlue,
            textAlign: 'center',
            width: "100%",
            height: "auto",
          }}
        >
            <Stack direction='row' spacing={3} marginLeft={3} > {/*alter margin */}
          <Typography 
           sx={{
            fontWeight: '750',
            fontFamily:'Raleway,sans-serif', 
            fontSize:'4.5rem'}}>{number}</Typography>
          <Stack direction='column' sx={{alignItems:'start'}} >
          <Typography paddingTop={3.5} paddingRight={3} sx={{fontWeight:'bold',fontFamily:'Raleway, sans-serif',fontSize:'1.3rem'}}>{title}</Typography>
          <Typography paddingTop={0} paddingBottom={3.5} sx={{fontFamily:'Raleway, sans-serif', fontWeight:'300'}}>{content}</Typography>
          </Stack>
          </Stack>
        </Paper>
      </Container>
    );
  };
  
  export default ModuleTitle;