import ModuleStep from "../../components/ModuleStep";
import ModuleTitle from "../../components/ModuleTitle";
import ModuleLink from "../../components/ModuleLink";
import {Stack, Typography } from '@mui/material';
import ModuleQuestion from "../../components/ModuleQuestion";

const ModuleSeven = () => {
    return (

        <Stack direction='column' >
            <ModuleTitle
                number='7'
                title='Welcome to Step 7:'
                content='Clinical Trial Setup'>
            </ModuleTitle>
            <ModuleStep
                title='7.1 Questions to Check if NIH Standards for Clinical Trials are Met'
                content='For clinical trials, there are additional steps that an investigator must do. 
                Clinical trials are clinical research studies involving human participants assigned to an intervention 
                in which the study is designed to evaluate the effect(s) of the intervention on the participant and the 
                effect being evaluated is a health-related biomedical or behavioral outcome.
                You can determine if you meet the NIH standard definition of clinical trial by answering the following questions.'>
                <ModuleQuestion
                question='1. Does your study involve human participants?'
                yesResponse={<Typography sx={{fontFamily:'Raleway, sans-serif', fontSize:'.8rem'}}>YES, go to the next question</Typography>}
                noResponse={<Typography sx={{fontFamily:'Raleway, sans-serif', fontSize:'.8rem'}}>NO</Typography>}>
                </ModuleQuestion>
                <ModuleQuestion
                question='2. Are the participants prospectively assigned to an intervention?'
                yesResponse={<Typography sx={{fontFamily:'Raleway, sans-serif', fontSize:'.8rem'}}>YES, go to the next question</Typography>}
                noResponse={<Typography sx={{fontFamily:'Raleway, sans-serif', fontSize:'.8rem'}}>NO</Typography>}>
                </ModuleQuestion>
                <ModuleQuestion
                question='3. Is the study designed to evaluate the effect of the intervention on the participants?'
                yesResponse={<Typography sx={{fontFamily:'Raleway, sans-serif', fontSize:'.8rem'}}>YES, go to the next question</Typography>}
                noResponse={<Typography sx={{fontFamily:'Raleway, sans-serif', fontSize:'.8rem'}}>NO</Typography>}>
                </ModuleQuestion>
                <ModuleQuestion
                question='4. Is the effect being evaluated a health-related biomedical or behavioral outcome?'
                yesResponse={<Typography sx={{fontFamily:'Raleway, sans-serif', fontSize:'.8rem'}}>YES, go to the evaulation!</Typography>}
                noResponse={<Typography sx={{fontFamily:'Raleway, sans-serif', fontSize:'.8rem'}}>NO</Typography>}>
                </ModuleQuestion>
            </ModuleStep>

            <ModuleStep
                title='7.2 Evaluate Results'
                content="If the answers to the 4 questions are YES, your study meets the NIH definition of a clinical trial, even if…">
                <Typography sx={{paddingX: 7, fontFamily:'Raleway, sans-serif', fontSize:'.8rem'}}>
                    -You are studying healthy participants 
                    <br></br>
                    -Your study does not have a comparison group (e.g., placebo or control), or has a single arm 
                    <br></br>
                    -Your study is only designed to assess the pharmacokinetics, safety, and/or maximum tolerated dose of an investigational drug 
                    <br></br>
                    -Your study is utilizing a behavioral intervention, or measuring intent to change behavior 
                    <br></br>
                    -Only one aim or sub-aim of your study meets the clinical trial definition 
                    <br></br>
                    -Your study is no more than minimal risk
                    <br></br>
                    <br></br></Typography>

                    <Typography sx={{paddingX: 5, fontFamily:'Raleway, sans-serif', fontSize:'.8rem'}}>

                    Note: Studies intended solely to refine measures are not considered clinical trials. Studies that solely involve secondary research with 
                    biological specimens or health information are not clinical trials.</Typography>
            <ModuleLink
            link='https://register.clinicaltrials.gov/'
            text='A. If all four YES above- Ok great, we have determined your study is a clinical trial. You must register your trial on ClinicalTrials.gov.'>
            </ModuleLink>
            <ModuleLink
            link='https://www.research.uky.edu/office-sponsored-projects-administration/clinicaltrialsgov'
            text='Contact your institutional administrator to get account setup and login information.'>
            </ModuleLink>
            </ModuleStep>
            <ModuleStep
            title='7.3 Additional Considerations'
            content='Additional considerations could be the following:'>
                <ModuleQuestion
                question='Are you using clinical services in a healthcare setting?'
                yesResponse={<Typography sx={{fontFamily:'Raleway, sans-serif', fontSize:'.8rem'}}>Consider sending your protocol to the Clinical Research Support Office (CRSO) so they can determine if you require their services or need coverage analysis (determination if you have study related items or services that can be billed to patient insurance or if you have research related charges only). [https://www.research.uky.edu/clinical-research-support-office] </Typography>}
                noResponse={<Typography sx={{fontFamily:'Raleway, sans-serif', fontSize:'.8rem'}}>Go to question 2</Typography>}>
                </ModuleQuestion>
                <ModuleQuestion
                question='Do you need help with clinical services?'
                yesResponse={<Typography sx={{fontFamily:'Raleway, sans-serif', fontSize:'.8rem'}}>No problem, some institutions have support for this. Contact the Center for Clinical and Translational Science (CCTS) and let them know what services you might need. [https://www.ccts.uky.edu/]</Typography>}
                noResponse={<Typography sx={{fontFamily:'Raleway, sans-serif', fontSize:'.8rem'}}>Congratulations, you have completed the approval steps to get your study approved and implemented.</Typography>}>
                </ModuleQuestion>
            </ModuleStep>
       </Stack>

      );
    };
    
export default ModuleSeven;