import ModuleStep from "../../components/ModuleStep";
import ModuleTitle from "../../components/ModuleTitle";
import ModuleLink from "../../components/ModuleLink";
import {Box, Stack, Typography } from '@mui/material';
import ModuleQuestion from "../../components/ModuleQuestion";

const ModuleOne = () => {
    return (

        <Stack direction='column' >
            <ModuleTitle
                number='1'
                title='Welcome to Step 1:'
                content='IRB Review'>
            </ModuleTitle>
            <ModuleStep
                title='1.1 Get Started with IRB'
                content='An Institutional Review Board (IRB) is a committee that reviews
                 research studies for an institution for any research involving
                  human subjects. IRBs are established to ensure that research involving
                   human subjects is conducted ethically and in accordance with federal, 
                   state, and institutional regulations in addition to protecting the 
                   rights and welfare of research participants. IRBs may also be referred to as 
                   Independent Review Boards, Ethics Review Committees, or Research Ethics Boards. If you are new to 
                   IRB submissions, additional information can be found at: '>
                <ModuleLink
                link='https://www.research.uky.edu/office-research-integrity/getting-started'
                text='Getting Started with IRB'>

                </ModuleLink>
            </ModuleStep>

            <ModuleStep
                title='1.2 Background Information'
                content="This process usually takes the longest to get approved so lets get started 
                  with generating some IRB needed information. But first we need some background information">

             <ModuleQuestion
             question='Is this project associated with a grant/funding?'
             yesResponse={<>
                <Box paddingX={4}>
                <Typography sx={{fontFamily: 'Raleway,sans-serif', fontSize: '.8rem'}}>Please upload your grant or project narrative here. </Typography>
                </Box>
                {/* come back with document upload stuff */}
             </>}
             noResponse={<>
             <Box
                sx={{paddingX:4.5}}>
                <Typography sx={{fontFamily: 'Raleway,sans-serif', fontSize: '.8rem'}}>That's okay. Lets start from scratch. Follow the instructions of your institution's IRB 
                    review process. 
                </Typography>
                
                <ModuleLink
                    link='https://ris.uky.edu/irb/DashBoard/login.aspx'
                    text='E-IRB Login'

                    >
                    </ModuleLink>
                    </Box>
              </>
            }>
                </ModuleQuestion>   
            </ModuleStep>
            <ModuleStep title= '1.3 Required Trainings for Approval'
            content= 'In order to submit your IRB, you must have the required trainings for approval. You most likely completed these during onboarding but in case you haven’t, for IRB purposes, you’ll need to complete the following: '
            >
                <br
                ></br>
                <Typography sx={{paddingX: 5, fontFamily:'Raleway, sans-serif', fontSize:'.8rem'}}>1. Human Subjects Protection Training (HSP)- Done online via CITI. </Typography>
                <ModuleLink
                    link='https://www.research.uky.edu/office-research-integrity/human-subject-protection-hsp-training-faqs'
                    text='HSP'>

                </ModuleLink>
                <Typography sx={{paddingX: 5,fontFamily: 'Raleway,sans-serif', fontSize: '.8rem'}}>2. Responsible Conduct in Research (RCR)- Done online via CITI. </Typography>
                <ModuleLink
                    link='https://www.research.uky.edu/responsible-conduct-research'
                    text='RCR online'>

                </ModuleLink>
                <Typography sx={{paddingX: 5,fontFamily: 'Raleway,sans-serif', fontSize: '.8rem'}}>3. Responsible Conduct in Research (RCR)- Done in-person via an in-person training/discussion session handled by a department trainer.(Not all universities require this training) </Typography>
                <ModuleLink
                    link='https://www.research.uky.edu/responsible-conduct-research-scholarly-activity/rcr-inperson-training'
                    text='RCR in person'>

                </ModuleLink>
                <Typography sx={{paddingX: 5,fontFamily: 'Raleway,sans-serif', fontSize: '.8rem'}}>4. Good Clinical Practice (GCP)- Optional Sponsor/Investigator Requirement done online via CITI with the expectation that investigators and staff involved in the conduct, oversight, or management of clinical trials complete this training as well. </Typography>
                <ModuleLink
                    link='https://www.research.uky.edu/office-research-integrity/sponsor-investigator-gcp-citi-training-faqs'
                    text='GCP'>

                </ModuleLink>    
                
            </ModuleStep>
       </Stack>

      );
    };
    
export default ModuleOne;