import { Container, Paper, Typography, TextField, Stack, Box, Button } from '@mui/material';
import { Link } from 'react-router-dom';
import colors from '../assets/Colors'


const Login = ({onLogin}) => { 
    return (
        <>
        <Container 
            maxWidth='lg' 
             disableGutters // Removes default padding/margin
            sx={{  width: 'auto', height: "100%",display:"flex", justifyContent:'center', alignItems:'center', paddingY: 5 }}
        >
            <Paper
                square={false} 
                elevation={2} 
                className='title'
                sx={{
                  padding:2,
                  width:'100%',
                  maxWidth:'400px',
                  color:colors.color1Blue,
                  objectFit:'cover',
                  textAlign: 'left', 
                  backgroundColor: colors.color2Blue,  }}>
                        <Stack direction='column' spacing={2}>
                        <Typography 
                         sx={{
                             fontFamily: 'Raleway, sans-serif',
                             fontSize: '1rem',
                             lineHeight: '140%',
                             letterSpacing:' 5%'}}
                             >Sign in to your account
                        </Typography>
                        <Box
                        component="form"
                        noValidate
                        autoComplete={false}
                        sx={{ '& .MuiTextField-root': { paddingBottom: 3 }, display: "flex", 
                        flexDirection: "column", 
                        alignItems: "center", 
                         }}
                        >
                            <TextField 
                                label="Email" 
                                fontFamily =  "Raleway, sans-serif"
                                variant="outlined" 
                                fullWidth 
                                size='small'
                                 sx={{
                                    "& .MuiInputLabel-root": { fontFamily: "Raleway, sans-serif", fontSize: "1rem", color: "gray" }, //font of label 
                                    "& .MuiInputLabel-root.Mui-focused": { color: 'darkblue' }, // when hovered the color of the font
                                    "& .MuiInputBase-root": { backgroundColor: "white" },
                                    "& .MuiInputBase-root.Mui-focused": { color: 'darkblue' }, // when hovered the color of the font
                                    }}
                                
                            />
                            <TextField 
                                label="Password" 
                                //could show input addornment
                                fontFamily =  "Raleway, sans-serif"
                                variant="outlined" 
                                fullWidth 
                                size='small'
                                 sx={{
                                    "& .MuiInputLabel-root": { fontFamily: "Raleway, sans-serif", fontSize: "1rem", color: "gray" }, //font of label 
                                    "& .MuiInputLabel-root.Mui-focused": { color: 'darkblue' }, // when hovered the color of the font
                                    "& .MuiInputBase-root": { backgroundColor: "white" },
                                    "& .MuiInputBase-root.Mui-focused": { color: 'darkblue' }, // when hovered the color of the font
                                    }}
                                
                            />
                            <Button 
                            // does just click of button but once 
                            // login actually done don't want to do just click of 
                            // button without login confirmed/authentication occurs  
                            onClick={() => onLogin('signedIn')}
                            component={Link} to='/dashboard' size='small' variant='contained' sx={{backgroundColor: colors.color1Blue, fontFamily: 'Raleway, sans-serif'}}>Sign In
                            </Button>
                            <Typography 
                             sx={{
                                 fontFamily: 'Raleway, sans-serif',
                                 paddingTop:4,
                                 fontSize: '.8rem',
                                 letterSpacing:' 5%',
                                 color:colors.color1Blue
                                }}>Don't have an account?
                                <Button   
                                 sx={{
                                     color: colors.darkBlue,
                                     fontSize: '.8rem',
                                     minWidth:'auto',
                                     paddingLeft:.5,
                                
                                     textTransform:'none',
                                     fontFamily: 'Raleway, sans-serif'}}>Sign In
                                </Button>
                            </Typography>
                        </Box>
                    </Stack>
            </Paper>
        </Container>
        </>
    );
}

export default Login;
