import React, { useState } from 'react';
import { Container, Paper, Box, Button, TextField, Typography, IconButton } from '@mui/material';
import { Description as FileIcon, Visibility as ViewIcon } from '@mui/icons-material';
import colors from '../assets/Colors';
import '../assets/font.css';

function Dashboard() {
  const [editMode, setEditMode] = useState(false);
  const [projectEditMode, setProjectEditMode] = useState(false);
  const [profilePic, setProfilePic] = useState(null);
  const [name, setName] = useState("Name");
  const [title, setTitle] = useState("Title");
  const [shortSummary, setShortSummary] = useState("Short Summary of current projects etc.");
  const [longSummary, setLongSummary] = useState("Longer summary of current work...");
  const [projectName, setProjectName] = useState("Test Project");
  const [projectDesc, setProjectDesc] = useState("Project Description");
  const [sections, setSections] = useState({
    gcp: { 
      text: "", 
      file: null,
      description: "Good Clinical Practice documentation" 
    },
    rcr: { 
      text: "", 
      file: null,
      description: "Responsible Conduct of Research materials" 
    },
    cv: { 
      text: "", 
      file: null,
      description: "Curriculum Vitae" 
    },
    biosketch: { 
      text: "", 
      file: null,
      description: "Professional biography and sketch" 
    },
    fd: { 
      text: "", 
      file: null,
      description: "Financial disclosure statements" 
    },
    ad: { 
      text: "", 
      file: null,
      description: "Any additional relevant information" 
    }
  });

  const handleImageUpload = (e) => {
    if (!editMode) return;
    const file = e.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setProfilePic(reader.result);
      reader.readAsDataURL(file);
    }
  };

  const handleSectionFileUpload = (section, e) => {
    if (!projectEditMode) return;
    const file = e.target.files[0];
    if (file) {
      setSections(prev => ({
        ...prev,
        [section]: { ...prev[section], file }
      }));
    }
  };

  const handleTextChange = (section, value) => {
    setSections(prev => ({
      ...prev,
      [section]: { ...prev[section], text: value }
    }));
  };

  const handleViewFile = (file) => {
    if (file) {
      window.open(URL.createObjectURL(file), '_blank');
    }
  };

  return (
    <Container maxWidth="lg" sx={{ py: 4, position: 'relative' }}>
      {/* Top Panel */}
      <Paper elevation={3} sx={{ 
        display: 'flex', 
        flexDirection: { xs: 'column', md: 'row' }, 
        gap: 4, 
        mb: 4, 
        bgcolor: colors.color1Blue, 
        color: colors.white,
        '& .MuiTextField-root': {
          '& .MuiInputBase-root': {
            color: colors.white,
          },
          '& .MuiInputLabel-root': {
            color: colors.white,
          },
          '& .MuiFilledInput-underline:before': {
            borderBottomColor: colors.white,
          },
          '& .MuiOutlinedInput-notchedOutline': {
            borderColor: colors.white,
          }
        }
      }}>
      {/* Left Column - Profile Picture */}
      <Box sx={{ 
        width: { xs: '100%', md: '30%' }, 
        pr: { md: 3 }, 
        mb: { xs: 2, md: 0 },
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',  
        padding: { xs: '10px', md: '20px' }
      }}>
        <Box sx={{ 
          width: '100%', 
          aspectRatio: '1/1', 
          bgcolor: colors.accentGrey,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          mb: 2,
          borderRadius: '4px',
          overflow: 'hidden'
        }}>
          {profilePic ? (
            <img src={profilePic} alt="Profile" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
          ) : (
            <Typography fontFamily={'Raleway, sans-serif'} sx={{ color: colors.white }}>Profile Image</Typography>
          )}
        </Box>
        {editMode && (
          <Button
            variant="contained"
            component="label"
            sx={{
              width: '100%',
              maxWidth: '300px',
              mt: 1,
              backgroundColor: colors.highlightOrange,
              color: colors.white,
              '&:hover': {
                backgroundColor: colors.color2Blue
              }
            }}
          >
            Choose File
            <input
              type="file"
              accept="image/*"
              onChange={handleImageUpload}
              hidden
            />
          </Button>
        )}
      </Box>

        {/* Right Column - Bio */}
        <Box sx={{ width: { xs: '100%', md: '70%' } }}>
          <Paper elevation={3} sx={{ 
            p: 3, 
            height: '100%', 
            position: 'relative', 
            bgcolor: 'transparent', 
            boxShadow: 'none',
            color: colors.white
          }}>
            {/* Edit Button (Top Right) */}
            <Box sx={{
              position: 'absolute',
              top: 20,
              right: 20,
              zIndex: 1,
            }}>
              <Button
                variant="contained"
                size="small"
                onClick={() => setEditMode(!editMode)}
                sx={{
                  minWidth: 80,
                  backgroundColor: colors.highlightOrange,
                  color: colors.white,
                  borderRadius: '50px',
                  fontSize: '12px',
                  fontWeight: 'bold',
                  boxShadow: 3,
                  '&:hover': {
                    backgroundColor: colors.color2Blue
                  }
                }}
              >
                {editMode ? 'Save Profile' : 'Edit Profile'}
              </Button>
            </Box>
            {editMode ? (
              <>
                <TextField
                  fullWidth
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  variant="filled"
                  margin="normal"
                  label="Name"
                  sx={{
                    '& .MuiFilledInput-root': {
                      color: colors.white,
                      '&:before': { borderBottomColor: colors.white },
                    },
                    '& .MuiInputLabel-root': { color: colors.white }
                  }}
                />
                <TextField
                  fullWidth
                  value={title}
                  onChange={(e) => setTitle(e.target.value)}
                  variant="filled"
                  margin="normal"
                  label="Title"
                  sx={{
                    '& .MuiFilledInput-root': {
                      color: colors.white,
                      '&:before': { borderBottomColor: colors.white },
                    },
                    '& .MuiInputLabel-root': { color: colors.white }
                  }}
                />
              </>
            ) : (
              <>
                <Typography fontFamily={'Raleway, sans-serif'} variant="h4" sx={{ color: colors.white }} gutterBottom>{name}</Typography>
                <Typography fontFamily={'Raleway, sans-serif'} variant="h6" sx={{ color: colors.white }} gutterBottom>{title}</Typography>
              </>
            )}
            
            <TextField
              fullWidth
              multiline
              value={shortSummary}
              onChange={(e) => setShortSummary(e.target.value)}
              variant="outlined"
              margin="normal"
              disabled={!editMode}
              sx={{
                '& .MuiOutlinedInput-root': {
                  color: colors.white,
                  '& fieldset': {
                    borderColor: colors.white,
                  },
                  '&.Mui-disabled fieldset': {
                    borderColor: 'transparent',
                  },
                },
                '& .MuiInputLabel-root': {
                  color: colors.white,
                },
                '& textarea': {
                  color: colors.white,
                },
              }}
            />

            
            <TextField
              fullWidth
              multiline
              rows={4}
              value={longSummary}
              onChange={(e) => setLongSummary(e.target.value)}
              variant="outlined"
              margin="normal"
              disabled={!editMode}
              sx={{
                '& .MuiOutlinedInput-root': {
                  color: colors.white,
                  '& fieldset': { borderColor: colors.white },
                  '&.Mui-disabled fieldset': { borderColor: 'transparent' }
                },
                '& .MuiInputLabel-root': { color: colors.white }
              }}
            />
          </Paper>
        </Box>
      </Paper>

      {/* Project Section */}
      <Paper elevation={3} sx={{ 
        p: 3, 
        mb: 4, 
        bgcolor: colors.color1Blue, 
        color: colors.white, 
        position: 'relative',
        '& .MuiTextField-root': {
          '& .MuiInputBase-root': {
            color: colors.white,
          },
          '& .MuiInputLabel-root': {
            color: colors.white,
          },
          '& .MuiFilledInput-underline:before': {
            borderBottomColor: colors.white,
          }
        }
      }}>
        {/* Project Edit Button */}
        <Box sx={{
          position: 'absolute',
          top: 20,
          right: 20,
          zIndex: 1,
        }}>
          <Button
            variant="contained"
            size="small"
            onClick={() => setProjectEditMode(!projectEditMode)}
            sx={{
              minWidth: 80,
              backgroundColor: colors.highlightOrange,
              color: colors.white,
              borderRadius: '50px',
              fontSize: '12px',
              fontWeight: 'bold',
              boxShadow: 3,
              '&:hover': {
                backgroundColor: colors.color2Blue
              }
            }}
          >
            {projectEditMode ? 'Save Project' : 'Edit Project'}
          </Button>
        </Box>

        {projectEditMode ? (
          <TextField
            fullWidth
            value={projectName}
            onChange={(e) => setProjectName(e.target.value)}
            variant="filled"
            margin="normal"
            label="Project Name"
            sx={{
              '& .MuiFilledInput-root': {
                color: colors.white,
                '&:before': { borderBottomColor: colors.white },
              },
              '& .MuiInputLabel-root': { color: colors.white }
            }}
          />
        ) : (
          <Typography fontFamily={'Raleway, sans-serif'} variant="h5" sx={{ color: colors.white, fontWeight: 'bold' }}>
            Project: {projectName}
          </Typography>
        )}
        
        <TextField
          fullWidth
          multiline
          value={projectDesc}
          onChange={(e) => setProjectDesc(e.target.value)}
          variant="outlined"
          margin="normal"
          disabled={!projectEditMode}
          label="Project Description"
          sx={{
            '& .MuiOutlinedInput-root': {
              color: colors.white,
              '& fieldset': {
                borderColor: colors.white,
              },
              '&.Mui-disabled fieldset': {
                borderColor: 'transparent',
              },
            },
            '& .MuiInputLabel-root': {
              color: colors.white,
            },
            '& textarea': {
              color: colors.white,
            },
          }}
        />

        {/* Six Sections */}
        <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', md: '1fr 1fr' }, gap: 3, mt: 4 }}>
          {[
            { title: "1 GCP", key: "gcp" },
            { title: "2 RCR", key: "rcr" },
            { title: "3 CV", key: "cv" },
            { title: "4 Biosketch", key: "biosketch" },
            { title: "5 Financial Disclosures", key: "fd" },
            { title: "6 Additional Information", key: "ad" }
          ].map((item) => (
            <Paper key={item.key} elevation={3} sx={{
              p: 2,
              background: colors.colorLightBlue,
              color: colors.white
            }}>
              <Typography fontFamily={'Raleway, sans-serif'}variant='h6' sx={{ color: colors.white, fontWeight: 'bold' }} gutterBottom>
                {item.title}
              </Typography>
              <Typography fontFamily={'Raleway, sans-serif'} variant='body2' sx={{ color: colors.white, mb: 2 }}>
                {sections[item.key].description}
              </Typography>
              
              {(projectEditMode || sections[item.key].text) && (
                <TextField
                  fullWidth
                  multiline
                  rows={3}
                  value={sections[item.key].text}
                  onChange={(e) => handleTextChange(item.key, e.target.value)}
                  variant="filled"
                  disabled={!projectEditMode}
                  sx={{ 
                    mb: 2,
                    '& .MuiFilledInput-root': {
                      backgroundColor: 'transparent',
                      color: colors.white,
                      '&:before': {
                        borderBottom: projectEditMode ? `1px solid ${colors.white}` : 'none'
                      },
                      '&:hover:before': {
                        borderBottom: projectEditMode ? `2px solid ${colors.white}` : 'none'
                      }
                    },
                    '& .MuiInputLabel-root': {
                      color: colors.white,
                    }
                  }}
                />
              )}
              
              <Box sx={{ 
                display: 'flex', 
                alignItems: 'center', 
                p: 1, 
                bgcolor: colors.color1Blue, 
                borderRadius: 1,
                mb: 2
              }}>
                {sections[item.key].file ? (
                  <>
                    <FileIcon sx={{ mr: 1, color: colors.white }} />
                    <Typography fontFamily={'Raleway, sans-serif'} variant="body2" sx={{ color: colors.white, flexGrow: 1 }}>
                      {sections[item.key].file.name}
                    </Typography>
                    <IconButton 
                      onClick={() => handleViewFile(sections[item.key].file)}
                      sx={{ color: colors.white }}
                    >
                      <ViewIcon />
                    </IconButton>
                  </>
                ) : (
                  <Typography fontFamily={'Raleway, sans-serif'} variant="body2" sx={{ color: colors.white }}>
                    No file uploaded
                  </Typography>
                )}
              </Box>
              
              {projectEditMode && (
                <Box sx={{ mt: 1 }}>
                  <input
                    type="file"
                    onChange={(e) => handleSectionFileUpload(item.key, e)}
                    style={{ width: '100%' }}
                  />
                </Box>
              )}
            </Paper>          
          ))}
        </Box>
      </Paper>
    </Container>
  );
};

export default Dashboard;