// component for Yes and No buttons for ModuleQuestion component
//      shouldn't be necessary to use outside ModuleQuestion

// onAnswer - sets the state in ModuleQuestion component
//         based on which button is pressed, changes the content 
//         of card

import { Stack,Button } from "@mui/material";
import colors from "../assets/Colors";

const ModuleYesNo = ({onAnswer}) => {

return(
<Stack direction='row' spacing={2}  sx={{justifyContent: "center"}} >
    <Button 
        onClick={() => onAnswer('yes')}
        sx=
        {{ bgcolor:colors.highlightOrange, 
            color: colors.white, 
            borderRadius: '50px', 
            boxShadow: 5, 
            fontSize: '12px', 
            fontWeight: 'bold', 
            fontFamily:'Raleway, sans-serif',
            mt: '20px'
            }}>
            Yes
        </Button>
        <Button 
        onClick={() => onAnswer('no')}
        sx=
        {{ bgcolor:colors.highlightOrange, 
            color: colors.white, 
            borderRadius: '50px', 
            boxShadow: 5, 
            fontSize: '12px', 
            fontWeight: 'bold', 
            fontFamily:'Raleway, sans-serif',
            mt: '20px'
        }}>
        No
        </Button>
</Stack>
)
}

export default ModuleYesNo;
