// component for orange start button for the steps on Post
// Award page -- only used in PostAwardStep so far --

// <StartButton
//  path= 'desired path to go to'
// ></StartButton>

import colors from '../assets/Colors'
import { Link } from 'react-router-dom';
import '../assets/font.css'
import { Container, Paper,Button, Typography, Stack } from '@mui/material';

const StartButton = ({ path }) => {
    return (
    <Button 
        component={Link}
        to={path} sx={{ bgcolor: colors.highlightOrange, color: colors.white, fontFamily: 'Raleway,sans-serif',borderRadius: '50px', boxShadow: 5, fontSize: '14px', fontWeight: 'bold', 
        left: '30%',    
        mt: '40px',
        width: '90px',
        height: '50px'
    }}>
    Start
    </Button>

);};

export default StartButton;


