// component for text buttons on the header
// <HeaderButton
//  webPath= desired webpath/page want to go to; correlates with Routes on App.js
//  name= text for button
// ></HeaderButton>

import { Box,Button } from "@mui/material";
import colors from "../assets/Colors";
import { Link } from 'react-router-dom';


const HeaderButton= ({webPath, name}) =>{
return (
    <Button 
        component={Link}
        to={webPath}
        color="inherit"
        sx={{ fontFamily: 'Raleway, sans-serif',color: colors.darkBlue, textTransform: 'none', fontSize: '1rem', fontWeight: 'medium' }}>
        {name}
    </Button>
);
};
export default HeaderButton;