// component for Step boxes that describe the steps
// on Post Award Page
// contains StartButton component

/* <PostAwardStep
        stepNumber= number of step
        stepName = title of step
        webPath = '/postAward/pathToNextStep
    ></PostAwardStep> */



import colors from '../assets/Colors'
import '../assets/font.css'
import StartButton from './StartButton';
import { Container, Paper, Typography, Stack } from '@mui/material';


const PostAwardStep = ({ stepNumber, stepName, webPath }) => {
    return (
<Paper elevation='3' sx={{ width: '35vh', height: '30vh', bgcolor: colors.color1Blue, color: colors.white, 
    pt: '10px',
    pl: '15px',
    pr: '15px'
    }}>
    <Typography fontFamily={'Raleway, sans-serif'} fontSize={'18px'} fontWeight={'bold'}>Step {stepNumber}:</Typography>
    <Typography fontFamily={'Raleway, sans-serif'} fontSize={'15px'} fontWeight={'medium'} sx={{ mt: '15px'}}>
        {stepName}
    </Typography>
    <StartButton
        path={webPath}
    ></StartButton>

</Paper>
    );};

    export default PostAwardStep;